<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/functions.php';$u=requireRole('user','member','admin');$error='';if(post()){verifyCsrf();$action=$_POST['action']??'profile';try{if($action==='profile'){$name=clean('full_name',150);$email=$u['email'];if(!(int)$u['email_verified']){$email=emailField('email');if(!$email)throw new RuntimeException('Please enter a valid email address.');}$phone=clean('phone',40);$occupation=clean('occupation',150);$bio=clean('bio',3000);if(mb_strlen($name)<2)throw new RuntimeException('Please enter a valid name.');$photo=safeFileUpload('profile_photo');if($photo)db()->prepare('UPDATE users SET full_name=?,email=?,phone=?,occupation=?,bio=?,profile_photo=? WHERE id=?')->execute([$name,$email,$phone,$occupation,$bio,$photo,$u['id']]);else db()->prepare('UPDATE users SET full_name=?,email=?,phone=?,occupation=?,bio=? WHERE id=?')->execute([$name,$email,$phone,$occupation,$bio,$u['id']]);flash('success','Profile updated.');redirect('profile.php');}}catch(Throwable $e){error_log($e->getMessage());$error=$e->getMessage();}}
$history=[];$pending=[];$events=[];$s=db()->prepare("SELECT c.*,e.title_en,e.event_date,e.location FROM participation_claims c JOIN events e ON e.id=c.event_id WHERE c.member_id=? AND c.status='verified' ORDER BY c.participation_date DESC");$s->execute([$u['id']]);$history=$s->fetchAll();if($u['role']==='member'){$s=db()->prepare("SELECT c.*,e.title_en,e.event_date FROM participation_claims c JOIN events e ON e.id=c.event_id WHERE c.member_id=? AND c.status='pending' ORDER BY c.created_at DESC");$s->execute([$u['id']]);$pending=$s->fetchAll();$events=db()->query('SELECT id,title_en,event_date FROM events WHERE event_date<=CURDATE() ORDER BY event_date DESC LIMIT 100')->fetchAll();}$pageTitle='Settings';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Account settings</p><h1 class="section-title">Your profile.</h1><?php if($error):?><div class="flash error" style="position:static;margin:20px 0"><?=e($error)?></div><?php endif;?><div class="grid-3" style="margin-top:30px"><div class="form-shell" style="margin:0;grid-column:span 2"><h2>Profile information</h2><form method="post" enctype="multipart/form-data"><?=csrfField()?><input type="hidden" name="action" value="profile"><div class="field"><label>Full name</label><input name="full_name" value="<?=e($u['full_name'])?>" required></div><div class="field"><label>Username</label><input value="<?=e($u['username'])?>" disabled></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($u['email'])?>" <?=((int)$u['email_verified'])?'disabled':''?>><small class="help"><?=((int)$u['email_verified'])?'Verified email cannot be changed.':'You may correct your email until an administrator verifies it.'?></small></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($u['phone'])?>"></div><div class="field"><label>Occupation</label><input name="occupation" value="<?=e($u['occupation'])?>"></div><div class="field"><label>Bio</label><textarea name="bio"><?=e($u['bio'])?></textarea></div><div class="field"><label>Profile photo</label><input type="file" name="profile_photo" accept="image/jpeg,image/png,image/gif,image/webp"><small class="help">Stored securely through ImgBB; only the URL is saved in the database.</small></div><button class="btn primary">Save profile</button></form></div><div class="feature"><h3>Account status</h3><p><span class="pill"><?=e($u['role'])?></span></p><p>Email verification: <b><?=((int)$u['email_verified'])?'Verified':'Waiting for admin'?></b></p><p>Account: <b><?=((int)$u['is_active'])?'Active':'Inactive'?></b></p><?php if($u['role']==='member'):?><hr><h3>Participation</h3><p>Only admin-verified claims become official activity history.</p><form method="post" action="claim-participation.php"><?=csrfField()?><div class="field"><label>Past event</label><select name="event_id" required><option value="">Select an event</option><?php foreach($events as $ev):?><option value="<?=$ev['id']?>"><?=e($ev['title_en'])?> · <?=e($ev['event_date'])?></option><?php endforeach;?></select></div><div class="field"><label>Date</label><input type="date" name="participation_date" required></div><div class="field"><label>Details</label><textarea name="details" placeholder="Describe your participation"></textarea></div><button class="btn coral">Request verification</button></form><?php endif;?></div></div><?php if($u['role']==='member'):?><div class="form-shell" style="max-width:none;margin-top:30px"><h2 id="activity-history">Official activity history</h2><?php if(!$history):?><p>No verified participation yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Location</th><th>Details</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['title_en'])?></td><td><?=e($h['participation_date'])?></td><td><?=e($h['location'])?></td><td><?=e($h['details'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><div class="form-shell" style="max-width:none;margin-top:30px"><h2 id="pending-claims">Pending claims</h2><?php if(!$pending):?><p>No pending claims.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($pending as $p):?><tr><td><?=e($p['title_en'])?></td><td><?=e($p['participation_date'])?></td><td><?=e($p['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php endif;?></div></section><?php require dirname(__DIR__).'/includes/footer.php';
